-- 外研社八下 wy8B 听力灌库(junior_listening_exercises)· publisher=junior_fltrp · volume=wy8B · grade=8 · 6单元×6=36
-- 3对话+2独白+1通知/单元 · 每篇2题4选1 · UK英音单音色(speaker=fable) · audio_url先NULL(跑pregenerate --volume=wy8B后回填)
-- 语法点:U1被动(现在/将来) U2被动(过去) U3情态一(能力/义务/许可) U4情态二(推测) U5宾从that U6宾从if/whether/wh
-- ★DELETE 带 publisher='junior_fltrp' AND volume='wy8B' 双限★
BEGIN;
DELETE FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8B';
INSERT INTO public.junior_listening_exercises
  (id, grade, publisher, volume, unit, title, topic, transcript, translation_cn, audio_url, speaker, kind, duration_sec, difficulty, questions, key_vocab) VALUES
  ('b7b822ed-5aac-4ccf-56ef-46652969b5bc', 8, 'junior_fltrp', 'wy8B', 'U1', 'How is bread made?', '面包怎么做(被动现在)', 'A: Dad, how is bread made in a factory?
B: Good question. First, flour and water are mixed together.
A: And then?
B: The dough is baked in a big hot oven. After that, the bread is packed into bags.
A: So it''s all done by machines?
B: Most of it. Then the bread is sent to shops early every morning.', 'A:爸爸,工厂里面包是怎么做的?B:好问题。首先,面粉和水被混合在一起。A:然后呢?B:面团在大热炉里被烤,之后面包被装进袋子。A:所以全是机器做的?B:大部分。然后面包一大早被送到店里。', NULL, 'fable', 'dialogue', 31, 1, '[{"type": "choice", "q": "What is done first when bread is made?", "options": ["The dough is baked.", "The bread is packed.", "The bread is sent to shops.", "Flour and water are mixed."], "answer": "D", "explanation": "''First, flour and water are mixed together.''"}, {"type": "choice", "q": "What is the dialogue mainly about?", "options": ["How to buy bread.", "How bread is made in a factory.", "Why bread is cheap.", "How to bake at home."], "answer": "B", "explanation": "全文讲工厂如何做面包(被动)。"}]'::jsonb, '[{"word": "flour", "cn": "面粉"}, {"word": "dough", "cn": "面团"}, {"word": "oven", "cn": "烤炉"}]'::jsonb),
  ('87e47b9a-ec15-fb70-d410-a450595b12d6', 8, 'junior_fltrp', 'wy8B', 'U1', 'Jobs of the future', '未来职业(被动将来)', 'A: What jobs will people do in the future, Ms Wu?
B: Many new jobs will be created. Some old ones will be done by robots.
A: Will teachers be needed?
B: Yes, of course! People will always be taught by real teachers.
A: That''s good to hear.
B: New skills will be needed too, so keep learning.', 'A:吴老师,未来人们会做什么工作?B:许多新工作会被创造出来,一些旧的会由机器人完成。A:还需要老师吗?B:当然!人们永远由真人老师教。A:听着真好。B:也会需要新技能,所以要不断学习。', NULL, 'fable', 'dialogue', 29, 2, '[{"type": "choice", "q": "Who will teach people in the future?", "options": ["Real teachers.", "Robots.", "Computers.", "No one."], "answer": "A", "explanation": "''People will always be taught by real teachers.''"}, {"type": "choice", "q": "What is Ms Wu''s advice?", "options": ["Stop going to school.", "Buy a robot.", "Keep learning new skills.", "Choose an old job."], "answer": "C", "explanation": "''New skills will be needed too, so keep learning.''"}]'::jsonb, '[{"word": "created", "cn": "创造(create的过去分词)"}, {"word": "robot", "cn": "机器人"}, {"word": "skill", "cn": "技能"}]'::jsonb),
  ('b4c48958-91b6-77e4-5e8b-f73f293bb533', 8, 'junior_fltrp', 'wy8B', 'U1', 'At the newspaper office', '报社(被动现在)', 'A: This is where our school newspaper is made!
B: Wow. Who writes the stories?
A: They are written by students like us. Then they are checked by a teacher.
B: And how are the pictures added?
A: They are put in by computer. At last, the paper is printed here.
B: That''s amazing. So much work is done by the team!', 'A:这就是我们校报做出来的地方!B:哇,谁写报道?A:由我们这样的学生写,然后由老师检查。B:图片怎么加进去?A:用电脑放进去。最后报纸在这里印。B:太厉害了,这么多活儿都是团队做的!', NULL, 'fable', 'dialogue', 31, 1, '[{"type": "choice", "q": "Who checks the stories?", "options": ["A teacher.", "Students.", "Computers.", "Readers."], "answer": "A", "explanation": "''they are checked by a teacher.''"}, {"type": "choice", "q": "What is the dialogue mainly about?", "options": ["How to write a story.", "How the school newspaper is made.", "Why newspapers are old.", "How to draw pictures."], "answer": "B", "explanation": "全文讲校报制作(被动)。"}]'::jsonb, '[{"word": "newspaper", "cn": "报纸"}, {"word": "printed", "cn": "印刷(print的过去分词)"}]'::jsonb),
  ('32cd54b7-d952-20d2-2e62-85c0124aa985', 8, 'junior_fltrp', 'wy8B', 'U1', 'How chocolate is made', '独白·巧克力制作(被动现在)', 'Do you know how chocolate is made? It starts far away on a farm. First, the beans are picked from tall trees. Then they are dried in the sun and sent to a factory. There, the beans are cleaned and made into a smooth brown paste. Sugar and milk are added to give it a sweet taste. At last, the chocolate is shaped into bars and wrapped in paper. The next time you enjoy a bar, think of the long journey it has made.', '你知道巧克力是怎么做的吗?它始于远方的农场。首先,豆子从高高的树上被摘下,然后在太阳下晒干、送到工厂。在那里,豆子被清洗、做成顺滑的棕色酱。加入糖和奶给它甜味。最后,巧克力被做成条状、用纸包好。下次你享用时,想想它走过的漫长旅程。', NULL, 'fable', 'passage', 46, 1, '[{"type": "choice", "q": "What is added to give chocolate a sweet taste?", "options": ["Water and salt.", "Beans and paper.", "Sugar and milk.", "Sun and air."], "answer": "C", "explanation": "''Sugar and milk are added to give it a sweet taste.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["Why chocolate is bad.", "How to grow trees.", "Where to buy chocolate.", "The steps in which chocolate is made."], "answer": "D", "explanation": "全文讲巧克力制作步骤(被动)。"}]'::jsonb, '[{"word": "beans", "cn": "豆子"}, {"word": "paste", "cn": "酱,糊"}, {"word": "wrapped", "cn": "包(wrap的过去分词)"}]'::jsonb),
  ('94f19c0b-6e44-075e-0c3c-0ed12d785484', 8, 'junior_fltrp', 'wy8B', 'U1', 'Work in the future', '独白·未来的工作(被动将来)', 'Work will change a lot in the future. Many boring tasks will be done by machines, so people will have more time for creative work. Cars will be driven by computers, and letters will be sent in seconds. But some things will not change. Kind doctors will still be needed, and good teachers will always be valued. New kinds of jobs will be created too. To be ready, we must keep learning and stay curious about the world.', '未来工作会大变。许多枯燥的任务将由机器完成,所以人们有更多时间做有创意的工作。汽车将由电脑驾驶,信件几秒就被发出。但有些不会变:仍然需要善良的医生,好老师永远被珍视。今天想象不到的新工作会被创造。要做好准备,我们必须不断学习、对世界保持好奇。', NULL, 'fable', 'passage', 43, 2, '[{"type": "choice", "q": "What will do many boring tasks in the future?", "options": ["Machines.", "Teachers.", "Doctors.", "Students."], "answer": "A", "explanation": "''Many boring tasks will be done by machines.''"}, {"type": "choice", "q": "What does the writer suggest we do?", "options": ["Stop working.", "Avoid machines.", "Choose easy jobs.", "Keep learning and stay curious."], "answer": "D", "explanation": "''we must keep learning and stay curious.''"}]'::jsonb, '[{"word": "tasks", "cn": "任务"}, {"word": "creative", "cn": "有创造力的"}, {"word": "valued", "cn": "被珍视(value的过去分词)"}]'::jsonb),
  ('55b90826-b8b4-201a-950e-a0bd852b08b9', 8, 'junior_fltrp', 'wy8B', 'U1', 'Career Day', '通知·职业日(被动)', 'Hello, students. Here is some news about our Career Day. Next Friday, many jobs will be shown to you. In the morning, a doctor and a farmer will be invited to talk about their work. At noon, a short film will be played about jobs of the future. In the afternoon, your questions will be answered by real workers. Come and find out how your dream job is done. See you there!', '同学们好,关于职业日的通知。下周五,许多职业会展示给你们。上午,会邀请一位医生和一位农民来讲他们的工作。中午,会放一部关于未来职业的短片。下午,真正的工作者会回答你们的问题。来了解你梦想的工作是怎么做的。到时见!', NULL, 'fable', 'notice', 39, 1, '[{"type": "choice", "q": "Who will answer students'' questions in the afternoon?", "options": ["Teachers.", "Robots.", "Real workers.", "Parents."], "answer": "C", "explanation": "''your questions will be answered by real workers.''"}, {"type": "choice", "q": "What is Career Day about?", "options": ["A sports match.", "Showing students how different jobs are done.", "A film festival.", "A maths test."], "answer": "B", "explanation": "通知主体=展示各种职业。"}]'::jsonb, '[{"word": "invited", "cn": "邀请(invite的过去分词)"}]'::jsonb),
  ('580f7f8c-f9f0-c406-4562-82046ed074dc', 8, 'junior_fltrp', 'wy8B', 'U2', 'A lesson I was taught', '学到的一课(被动过去)', 'A: You look thoughtful, Ben. What''s up?
B: I was taught an important lesson today.
A: Oh? What happened?
B: My little sister was hurt, but I didn''t help at first. Later I was told to be kinder.
A: And how do you feel now?
B: I feel sorry. I was reminded of one thing: family comes first.', 'A:Ben你若有所思,怎么了?B:我今天学到了重要的一课。A:哦?怎么回事?B:妹妹受伤了,但我起初没帮忙。后来我被告知要更善良。A:你现在感觉怎样?B:我很内疚。我被提醒家人第一。', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "What was Ben told to be?", "options": ["Faster.", "Quieter.", "Stronger.", "Kinder."], "answer": "D", "explanation": "''I was told to be kinder.''"}, {"type": "choice", "q": "What lesson was Ben taught?", "options": ["Family comes first.", "Sisters are annoying.", "Homework is hard.", "Games are fun."], "answer": "A", "explanation": "'''I was reminded of one thing: family comes first.'''"}]'::jsonb, '[{"word": "thoughtful", "cn": "若有所思的"}, {"word": "reminded", "cn": "提醒(remind的过去分词)"}]'::jsonb),
  ('c77e6941-8bb5-03da-0836-53eae5739028', 8, 'junior_fltrp', 'wy8B', 'U2', 'The old photo', '老照片(被动过去)', 'A: This old photo was taken twenty years ago!
B: Really? Where was it taken?
A: In our village. That little house was built by my grandpa.
B: It looks lovely. Was it kept in good shape?
A: Yes. It was repaired last year, and now my cousins live there.
B: What a warm family story.', 'A:这张老照片是二十年前拍的!B:真的?在哪拍的?A:在我们村。那小房子是我爷爷建的。B:真好看,保存得好吗?A:是的,去年被修缮过,现在我表亲们住那儿。B:多温暖的家族故事。', NULL, 'fable', 'dialogue', 27, 2, '[{"type": "choice", "q": "Who built the little house?", "options": ["A worker.", "A cousin.", "The writer''s grandpa.", "A neighbour."], "answer": "C", "explanation": "''That little house was built by my grandpa.''"}, {"type": "choice", "q": "What happened to the house last year?", "options": ["It was sold.", "It was repaired.", "It was pulled down.", "It was painted red."], "answer": "B", "explanation": "''It was repaired last year.''"}]'::jsonb, '[{"word": "village", "cn": "村庄"}, {"word": "repaired", "cn": "修缮(repair的过去分词)"}]'::jsonb),
  ('6eda3ca0-28ec-1a5c-bc0e-5800ce86f9c5', 8, 'junior_fltrp', 'wy8B', 'U2', 'The school show last term', '上学期演出(被动过去)', 'A: Did you see the school show last term?
B: Yes! The songs were sung so beautifully.
A: And the stage was decorated with our own paintings.
B: Right. Everything was planned by the students.
A: We learnt a lot from it, didn''t we?
B: We did. A big job was finished by a small team.', 'A:你看上学期学校演出了吗?B:看了!歌唱得太美了。A:舞台还用我们自己的画装饰。B:对,一切都是学生策划的。A:我们从中学了很多,对吧?B:是的,一个大工程被一个小团队完成了。', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "Who planned everything for the show?", "options": ["The teachers.", "The parents.", "The students.", "A company."], "answer": "C", "explanation": "''Everything was planned by the students.''"}, {"type": "choice", "q": "What did they learn from the show?", "options": ["Shows are boring.", "Singing is easy.", "Stages are expensive.", "A big job can be finished by a small team."], "answer": "D", "explanation": "''A big job was finished by a small team.''"}]'::jsonb, '[{"word": "decorated", "cn": "装饰(decorate的过去分词)"}, {"word": "planned", "cn": "策划(plan的过去分词)"}]'::jsonb),
  ('2658c706-118b-9f08-2e54-dd1a25700ffe', 8, 'junior_fltrp', 'wy8B', 'U2', 'How I grew up', '独白·我的成长(被动过去)', 'When I was young, I was often looked after by my grandma. Every morning, warm noodles were cooked for me, and my school bag was packed by her hand. At night, old stories were told to me before I slept. I did not know how lucky I was. Last winter, my grandma became ill, and suddenly I was needed at home. I cooked, I cleaned, and I cared for her. That hard time taught me a lot. Growing up brings both pains and gains.', '小时候,我常被奶奶照顾。每天早上有热面条给我做好,书包由她亲手收拾。晚上睡前有老故事讲给我听。我不知道自己多幸运。去年冬天奶奶病了,忽然家里需要我。我做饭、打扫、照顾她。那段艰难的日子教了我很多。成长既有痛也有得。', NULL, 'fable', 'passage', 46, 1, '[{"type": "choice", "q": "What was done for the writer every morning?", "options": ["Warm noodles were cooked.", "Games were played.", "Books were read.", "A song was sung."], "answer": "A", "explanation": "''warm noodles were cooked for me.''"}, {"type": "choice", "q": "What is the main idea of the passage?", "options": ["Grandmas cook well.", "Growing up brings both pains and gains.", "Winter is cold.", "Noodles are cheap."], "answer": "B", "explanation": "''Growing up brings both pains and gains.''"}]'::jsonb, '[{"word": "looked after", "cn": "照顾"}, {"word": "packed", "cn": "收拾(pack的过去分词)"}]'::jsonb),
  ('5c8b3a6b-19ac-c078-85aa-2232ccfbaa64', 8, 'junior_fltrp', 'wy8B', 'U2', 'The broken cup', '独白·打碎的杯子(被动过去)', 'Last year, a beautiful cup was broken by me at home. It was my mother''s favourite, and I was really afraid. At first, the truth was hidden, and I said nothing. But that night, I was filled with worry. The next morning, I told my mother everything. To my surprise, I was not shouted at. Instead, I was hugged. ''We can mend most things, but we cannot buy honesty,'' she said. That day, an important lesson was learnt, and I have never forgotten it.', '去年,我在家打碎了一个漂亮的杯子。它是妈妈的最爱,我真的很害怕。起初我把真相藏起来,什么也没说。但那晚我满心忧虑。第二天早上,我把一切告诉妈妈。出乎意料,我没被吼,反而被拥抱。『东西能修,但诚实买不到,』她说。那天,一个重要的教训被学到,我从未忘记。', NULL, 'fable', 'passage', 46, 2, '[{"type": "choice", "q": "How did the mother react when told the truth?", "options": ["She shouted at the writer.", "She said nothing.", "She left the room.", "She hugged the writer."], "answer": "D", "explanation": "''I was not shouted at. Instead, I was hugged.''"}, {"type": "choice", "q": "What lesson was learnt?", "options": ["Cups are expensive.", "Mothers are strict.", "Honesty matters more than things.", "Lying is easy."], "answer": "C", "explanation": "''We can mend most things, but we cannot buy honesty.''"}]'::jsonb, '[{"word": "hidden", "cn": "隐藏(hide的过去分词)"}, {"word": "honesty", "cn": "诚实"}]'::jsonb),
  ('d5703437-e2a8-b38a-67f6-d1081ad83d58', 8, 'junior_fltrp', 'wy8B', 'U2', 'Our Class Wall', '班级记忆墙(被动 过去/将来)', 'Hello, students. Here is some news about our class wall. Last term, many happy days were shared, and good work was done by all of us. Next week, old photos will be shown, and short stories written by you will be put up. Come and see how much we have grown together. Everyone is welcome!', '同学们好,关于班级墙的通知。上学期,许多快乐的日子被大家分享,很多好作品也由我们共同完成。下周,老照片会被展示出来,你们写的小故事也会被贴上去。来看看我们一起成长了多少。欢迎每一个人!', NULL, 'fable', 'notice', 30, 2, '[{"type": "choice", "q": "What will be shown on the wall next week?", "options": ["Old photos.", "Short films.", "New books.", "Toys."], "answer": "A", "explanation": "''old photos will be shown.''"}, {"type": "choice", "q": "What is the class wall about?", "options": ["Selling old photos.", "Sharing and remembering our class time.", "A sports match.", "A maths test."], "answer": "B", "explanation": "通知主体=分享并记住班级时光(被动过去/将来)。"}]'::jsonb, '[{"word": "grown", "cn": "成长(grow的过去分词)"}, {"word": "share", "cn": "分享"}]'::jsonb),
  ('5f12c68d-e1c7-98ca-8e50-c6de7ba4c43e', 8, 'junior_fltrp', 'wy8B', 'U3', 'Team rules', '团队规则(情态 must/should)', 'A: We''re a team now, so we must work together.
B: Agreed. And we should listen to each other''s ideas.
A: Right. If someone makes a mistake, we mustn''t laugh.
B: Exactly. We have to help instead.
A: Can I be the one who writes down our plan?
B: Sure, you can. A good team shares the work.', 'A:我们现在是团队了,所以必须一起努力。B:同意,还应该听彼此的想法。A:对,如果有人出错,我们不能笑。B:没错,我们得帮忙才对。A:我能来写我们的计划吗?B:当然可以,好团队分担工作。', NULL, 'fable', 'dialogue', 30, 1, '[{"type": "choice", "q": "What must the team not do when someone makes a mistake?", "options": ["Laugh at them.", "Help them.", "Listen to them.", "Share work."], "answer": "A", "explanation": "''If someone makes a mistake, we mustn''t laugh.''"}, {"type": "choice", "q": "What is the dialogue mainly about?", "options": ["How to win a game.", "The rules a good team should follow.", "Why teams are boring.", "How to write fast."], "answer": "B", "explanation": "主题=团队规则(情态)。"}]'::jsonb, '[{"word": "agreed", "cn": "同意"}]'::jsonb),
  ('8a0ce494-a9e6-015b-7393-333ec8927408', 8, 'junior_fltrp', 'wy8B', 'U3', 'What can you do?', '各展所能(情态 can 能力)', 'A: For the class project, what can you do well, Sam?
B: I can draw, so I could design the poster.
A: Great! I can''t draw, but I can write.
B: Perfect. You could write the words, then.
A: And Lily can sing, so she may lead the song.
B: A team works best when everyone can use their own skill.', 'A:班级项目里,你擅长什么,Sam?B:我会画画,可以设计海报。A:好!我不会画,但我会写。B:完美,那你可以写文字。A:Lily会唱歌,她可以领唱。B:当每个人都能发挥自己的技能,团队最出色。', NULL, 'fable', 'dialogue', 31, 2, '[{"type": "choice", "q": "What can Sam do well?", "options": ["Sing.", "Write.", "Draw.", "Dance."], "answer": "C", "explanation": "''I can draw, so I could design the poster.''"}, {"type": "choice", "q": "What does the dialogue tell us about teams?", "options": ["Only leaders matter.", "Drawing is the most important.", "Teams should be small.", "A team works best when everyone uses their own skill."], "answer": "D", "explanation": "末句点题。"}]'::jsonb, '[{"word": "design", "cn": "设计"}, {"word": "poster", "cn": "海报"}]'::jsonb),
  ('fc44cb5b-ff88-255a-2df6-23928e2d7778', 8, 'junior_fltrp', 'wy8B', 'U3', 'May I join?', '请求加入(情态 may/can 许可)', 'A: May I join your football team?
B: Of course you may! Can you play well?
A: Not very well yet, but I can run fast and I''ll practise hard.
B: That''s the right spirit. You must come to training on time, though.
A: I will. When can I start?
B: You can start this afternoon. Welcome to the team!', 'A:我能加入你们足球队吗?B:当然可以!你踢得好吗?A:还不太好,但我跑得快,会努力练。B:这才对。不过你必须准时来训练。A:我会的,什么时候能开始?B:今天下午就能开始,欢迎加入!', NULL, 'fable', 'dialogue', 31, 1, '[{"type": "choice", "q": "When can A start?", "options": ["Tomorrow.", "This afternoon.", "Next week.", "Never."], "answer": "B", "explanation": "''You can start this afternoon.''"}, {"type": "choice", "q": "Why does the team welcome A?", "options": ["Because A plays perfectly.", "Because A is tall.", "Because A can run fast and will practise hard.", "Because A is the teacher."], "answer": "C", "explanation": "跑得快、肯练→接纳。"}]'::jsonb, '[{"word": "training", "cn": "训练"}, {"word": "spirit", "cn": "精神,态度"}]'::jsonb),
  ('ae0416af-e87d-eee8-0c73-93ce79245033', 8, 'junior_fltrp', 'wy8B', 'U3', 'What makes a great team', '独白·好团队(情态)', 'What makes a great team? First, every member must trust each other. When we trust, we can share our real ideas without fear. Second, we should help those who find a task hard. No one can do everything alone. Third, a good team must listen, even when people do not agree. A leader may guide the group, but everyone can lead in small ways. When we work like this, a difficult job can become easy, and we all grow stronger together.', '什么造就一支好团队?首先,每个成员必须彼此信任。当我们信任,就能无所畏惧地分享真实想法。其次,我们应帮那些觉得任务难的人。没人能独自做完一切。第三,好团队必须倾听,即使意见不合。领导可以引导团队,但每个人都能以小方式领导。这样合作,难事变易,我们一起变强。', NULL, 'fable', 'passage', 44, 1, '[{"type": "choice", "q": "What must every member of a great team do?", "options": ["Trust each other.", "Work alone.", "Lead the group.", "Stay quiet."], "answer": "A", "explanation": "''every member must trust each other.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["How to win a match.", "Why leaders are the best.", "How to work alone.", "What makes a great team."], "answer": "D", "explanation": "全文讲好团队的要素。"}]'::jsonb, '[{"word": "trust", "cn": "信任"}, {"word": "member", "cn": "成员"}]'::jsonb),
  ('b440bb2c-d5fe-df80-b8b6-5cf97c7074d3', 8, 'junior_fltrp', 'wy8B', 'U3', 'The class garden team', '独白·班级花园队(情态)', 'Our class had to build a small garden, and it looked impossible to everyone. The ground was hard, and we had very little time. But we had to try. Each person did what they could. The strong ones had to dig, while others planted seeds. When someone felt tired, a friend would say, ''You can rest; I''ll take over.'' We had to solve many problems, but we never gave up. In the end, a green garden was our reward. A team can do what one person cannot.', '我们班得建一个小花园,没人觉得我们能做到。地很硬,时间又少。但我们知道必须试。每个人做力所能及的。强壮的得挖土,其他人种种子。有人累了,朋友会说:『你可以歇,我来接手。』我们得解决很多问题,但从不放弃。最后,一座绿色花园是我们的回报。团队能做到个人做不到的事。', NULL, 'fable', 'passage', 48, 2, '[{"type": "choice", "q": "What did the strong members have to do?", "options": ["Plant seeds.", "Dig the ground.", "Rest.", "Write a plan."], "answer": "B", "explanation": "''The strong ones had to dig.''"}, {"type": "choice", "q": "What is the main idea?", "options": ["Gardens are hard to build.", "Strong people are the best.", "Rest is important.", "A team can do what one person cannot."], "answer": "D", "explanation": "''A team can do what one person cannot.''"}]'::jsonb, '[{"word": "dig", "cn": "挖"}, {"word": "reward", "cn": "回报,奖赏"}]'::jsonb),
  ('2c757d6d-0657-7e4e-4116-1bb7c05411f3', 8, 'junior_fltrp', 'wy8B', 'U3', 'Team Challenge Week', '团队挑战周(情态一 义务/许可)', 'Hello, students. Here is some news about our Team Challenge. Next Friday, each class will work as one big team. You must plan together and help each other. Everyone should share ideas, and no one can win alone. You may choose your own task, but you have to do it on time. A great team can do great things. Come and show your team spirit!', '同学们好,关于团队挑战的通知。下周五,每个班将作为一个大团队合作。你们必须一起计划、互相帮助。人人都应分享想法,没有人能独自取胜。你们可以选择自己的任务,但必须按时完成。伟大的团队能做出了不起的事。来展示你们的团队精神吧!', NULL, 'fable', 'notice', 35, 2, '[{"type": "choice", "q": "What must students do in the challenge?", "options": ["Work alone.", "Stay at home.", "Plan together and help each other.", "Play games."], "answer": "C", "explanation": "''You must plan together and help each other.''"}, {"type": "choice", "q": "What is the Team Challenge about?", "options": ["Working well as a team.", "A cooking test.", "A singing show.", "A shopping trip."], "answer": "A", "explanation": "通知主体=作为团队合作(must/should/can/may)。"}]'::jsonb, '[{"word": "challenge", "cn": "挑战"}, {"word": "spirit", "cn": "精神;风貌"}]'::jsonb),
  ('e45010a3-9fd8-9144-e148-d18759def56d', 8, 'junior_fltrp', 'wy8B', 'U4', 'Whose bag is this?', '推测物主(情态推测)', 'A: Look, someone has left a bag on the seat.
B: Whose can it be? It must be a student''s, look at the books.
A: It might be Tom''s. He sat here this morning.
B: It can''t be Tom''s. His bag is black, and this one is blue.
A: You''re right. Then it may be Lily''s.
B: Let''s take it to the office. Someone must be looking for it.', 'A:看,有人把包落在座位上了。B:会是谁的呢?一定是学生的,看这些书。A:可能是Tom的,他今早坐这儿。B:不可能是Tom的,他包是黑的,这个是蓝的。A:你说得对,那可能是Lily的。B:拿去办公室吧,肯定有人在找它。', NULL, 'fable', 'dialogue', 38, 1, '[{"type": "choice", "q": "Why can''t the bag be Tom''s?", "options": ["Tom''s bag is black, this one is blue.", "It is too small.", "Tom has gone home.", "It has no books."], "answer": "A", "explanation": "''It can''t be Tom''s. His bag is black, and this one is blue.''"}, {"type": "choice", "q": "What do they decide to do?", "options": ["Keep the bag.", "Take the bag to the office.", "Open the bag.", "Leave it there."], "answer": "B", "explanation": "''Let''s take it to the office.''"}]'::jsonb, '[{"word": "seat", "cn": "座位"}]'::jsonb),
  ('f6b56316-742d-8c1a-cd8f-807ef9720fd9', 8, 'junior_fltrp', 'wy8B', 'U4', 'She looks worried', '推测心事(情态推测)', 'A: Anna looks worried today. What could be wrong?
B: She might have a problem at home.
A: Or she may be worried about the test.
B: It can''t be the test. She''s the best student in class.
A: True. She must need someone to talk to.
B: Let''s go and ask if we can help.', 'A:Anna今天看着愁,会有什么事呢?B:她可能家里有事。A:或者她可能担心考试。B:不可能是考试,她是班上最好的学生。A:对,她一定需要人聊聊。B:去问问能不能帮她。', NULL, 'fable', 'dialogue', 29, 2, '[{"type": "choice", "q": "Why can''t Anna be worried about the test?", "options": ["She is ill.", "She has gone home.", "She is the best student in class.", "She likes tests."], "answer": "C", "explanation": "''It can''t be the test. She''s the best student in class.''"}, {"type": "choice", "q": "What do the two friends decide to do?", "options": ["Ignore Anna.", "Take the test.", "Tell the teacher.", "Ask if they can help Anna."], "answer": "D", "explanation": "''Let''s go and ask if we can help.''"}]'::jsonb, '[{"word": "worried", "cn": "担心的"}]'::jsonb),
  ('5a6eb706-1df8-0bb0-a315-e542c0c3894a', 8, 'junior_fltrp', 'wy8B', 'U4', 'The light in the window', '推测(情态推测)', 'A: There''s a light in old Mr Chen''s window. He may be back!
B: He can''t be back. He went to the city last week.
A: Then who could it be?
B: It might be his daughter. She often looks after his house.
A: That must be it. Should we say hello?
B: Yes, and we can ask if she needs any help.', 'A:陈老先生窗户里有灯,他可能回来了!B:不可能,他上周去城里了。A:那会是谁呢?B:可能是他女儿,她常帮着看房子。A:一定是这样。我们要打个招呼吗?B:好,还可以问她需不需要帮忙。', NULL, 'fable', 'dialogue', 33, 1, '[{"type": "choice", "q": "Who might be in the house?", "options": ["Mr Chen.", "A thief.", "Mr Chen''s daughter.", "A teacher."], "answer": "C", "explanation": "''It might be his daughter.''"}, {"type": "choice", "q": "What kind of neighbours are they?", "options": ["Kind and ready to help.", "Rude and noisy.", "Afraid and quiet.", "Angry and busy."], "answer": "A", "explanation": "打招呼、问需不需要帮忙→善良。"}]'::jsonb, '[{"word": "daughter", "cn": "女儿"}]'::jsonb),
  ('197537ae-3eb5-c332-8a3b-c36f91a16b9b', 8, 'junior_fltrp', 'wy8B', 'U4', 'The quiet new boy', '独白·安静的新同学(情态推测)', 'A new boy joined our class last week, and he sits alone every day. At first, he seemed proud to me. But then I noticed something. He may not know anyone here yet. He might feel shy in a new place. It can''t be easy to leave your old friends. So today, I sat next to him and smiled. ''You must be new,'' I said. ''Would you like to join us at lunch?'' His face lit up. Sometimes a small act of kindness is all a person needs.', '上周一个新男孩加入我们班,他每天独自坐着。起初我以为他一定很高傲。但后来我注意到:他可能还谁都不认识,可能在新地方害羞。离开老朋友一定不容易。所以今天我坐到他旁边、微笑。『你一定是新来的,』我说,『午饭要和我们一起吗?』他脸上一亮。有时一个小小的善举正是一个人所需要的。', NULL, 'fable', 'passage', 49, 1, '[{"type": "choice", "q": "Why did the writer first think the new boy was proud?", "options": ["He was rude.", "He shouted.", "He was rich.", "He sat alone every day."], "answer": "D", "explanation": "''he sits alone every day. At first, he seemed proud to me.''"}, {"type": "choice", "q": "What is the main idea?", "options": ["New students are proud.", "A small act of kindness can be what a person needs.", "Sitting alone is fun.", "Lunch is important."], "answer": "B", "explanation": "结尾点题。"}]'::jsonb, '[{"word": "noticed", "cn": "注意到"}, {"word": "lit up", "cn": "(脸)亮了起来"}]'::jsonb),
  ('a393d980-df27-7237-2029-22bc364a3293', 8, 'junior_fltrp', 'wy8B', 'U4', 'Reading the signs', '独白·读懂需要(情态推测)', 'Helping others often begins with careful watching. If an old man walks slowly with heavy bags, he may need a hand. If a child stands crying near a shop, she is probably lost. A classmate who says nothing all day could be feeling sad. These signs are quiet, but they are real. We can''t always know for sure what people feel, but we can ask kindly. ''Do you need any help?'' is a small question that can change someone''s whole day. To help well, we must first learn to notice.', '帮助他人常始于细心观察。如果一位老人提着重物慢慢走,他可能需要搭把手。如果一个孩子在店边哭,她可能迷路了。一个整天不说话的同学可能心里难过。这些迹象很安静,却真实。我们不总能确切知道别人的感受,但可以善意地问。『你需要帮忙吗?』这个小问题能改变某人的一整天。要帮得好,我们得先学会留意。', NULL, 'fable', 'passage', 50, 2, '[{"type": "choice", "q": "What might a child crying near a shop be?", "options": ["Hungry.", "Angry.", "Lost.", "Tired."], "answer": "C", "explanation": "''If a child stands crying near a shop, she is probably lost.''"}, {"type": "choice", "q": "What must we do first to help well?", "options": ["Give money.", "Stay quiet.", "Walk away.", "Learn to notice others'' needs."], "answer": "D", "explanation": "''To help well, we must first learn to notice.''"}]'::jsonb, '[{"word": "signs", "cn": "迹象"}, {"word": "lost", "cn": "迷路的"}]'::jsonb),
  ('b8e924a5-7e2e-491c-208b-b5c6768722b0', 8, 'junior_fltrp', 'wy8B', 'U4', 'Helping Hands Week', '助人周(情态二 推测)', 'Hello, students. Here is some news about our Helping Hands Week. Around us, someone may need a hand every day. An old neighbour might feel lonely, and a classmate could be having a hard time. Next week, look for these quiet signs. On Monday, see someone who may be alone. On Friday, we will share our kind stories. A little care can mean a lot!', '同学们好,关于『助人周』的通知。在我们身边,每天都可能有人需要帮助。一位老邻居也许感到孤单,一个同学可能正过得艰难。下周,留意这些安静的信号。周一,去看看某个可能孤单的人。周五,我们一起分享善举故事。一点点关心,意义重大!', NULL, 'fable', 'notice', 35, 2, '[{"type": "choice", "q": "What should students do on Monday?", "options": ["See someone who may be alone.", "Stay at home.", "Play sport.", "Do homework."], "answer": "A", "explanation": "''On Monday, see someone who may be alone.''"}, {"type": "choice", "q": "What is Helping Hands Week about?", "options": ["A sports week.", "Noticing and helping people who need care.", "A book sale.", "A film show."], "answer": "B", "explanation": "通知主体=留意并帮助需要关心的人(may/might/could 推测)。"}]'::jsonb, '[{"word": "lonely", "cn": "孤单的"}, {"word": "neighbour", "cn": "邻居"}]'::jsonb),
  ('0b7867ea-9bba-58f9-548e-81c607c6b23e', 8, 'junior_fltrp', 'wy8B', 'U5', 'I think nature is amazing', '谈自然(宾从that)', 'A: I think that nature is the most amazing teacher.
B: I agree. I believe that we can learn so much from it.
A: Did you know that some trees can live for a thousand years?
B: Really? I didn''t know that they lived so long.
A: Scientists say that old trees help the whole forest.
B: That''s wonderful. I hope that we will protect them.', 'A:我觉得大自然是最了不起的老师。B:同意,我相信我们能从中学到很多。A:你知道有些树能活一千年吗?B:真的?我不知道它们活这么久。A:科学家说古树帮助整片森林。B:太棒了,我希望我们会保护它们。', NULL, 'fable', 'dialogue', 34, 1, '[{"type": "choice", "q": "How long can some trees live?", "options": ["A hundred years.", "A thousand years.", "Ten years.", "A month."], "answer": "B", "explanation": "''some trees can live for a thousand years.''"}, {"type": "choice", "q": "What do both speakers believe about nature?", "options": ["We can learn a lot from it and should protect it.", "It is boring.", "It is dangerous.", "It is useless."], "answer": "A", "explanation": "两人都认为可学、该保护。"}]'::jsonb, '[{"word": "forest", "cn": "森林"}, {"word": "protect", "cn": "保护"}]'::jsonb),
  ('d70f3a37-9ac6-1a57-0cee-18e688d42ed5', 8, 'junior_fltrp', 'wy8B', 'U5', 'Scientists have found', '科学发现(宾从that)', 'A: I read that ants can talk to each other.
B: Really? How do we know that they can?
A: Scientists found that they use smells as messages.
B: That''s amazing. I always thought that ants were simple.
A: Me too! But now I believe that even small animals are clever.
B: Nature shows us that there is still so much to learn.', 'A:我读到蚂蚁能互相交流。B:真的?我们怎么知道它们能?A:科学家发现它们用气味当信息。B:太神奇了,我一直以为蚂蚁很简单。A:我也是!但现在我相信连小动物都很聪明。B:大自然告诉我们,还有太多要学。', NULL, 'fable', 'dialogue', 32, 2, '[{"type": "choice", "q": "How do ants send messages, according to scientists?", "options": ["By sound.", "By dancing.", "By light.", "By smells."], "answer": "D", "explanation": "''they use smells as messages.''"}, {"type": "choice", "q": "What does nature show us?", "options": ["Ants are simple.", "Science is boring.", "There is still so much to learn.", "Small animals are useless."], "answer": "C", "explanation": "''Nature shows us that there is still so much to learn.''"}]'::jsonb, '[{"word": "ants", "cn": "蚂蚁"}, {"word": "smells", "cn": "气味"}]'::jsonb),
  ('f3e4773d-2734-52c0-acae-16ec78151bae', 8, 'junior_fltrp', 'wy8B', 'U5', 'I know it will help', '相信(宾从that)', 'A: Our class is going to plant trees on the hill. Will you come?
B: Of course. I know that it will help the air.
A: Right. I''ve read that trees make the ground stronger too.
B: I think that we should do this every year.
A: I agree. I believe that small actions can change a lot.
B: Let''s tell everyone that nature needs our help.', 'A:我们班要去山上种树,你来吗?B:当然,我知道这会帮助空气。A:对,我读到树还能让土地更牢固。B:我觉得我们该每年都做。A:同意,我相信小行动能改变很多。B:让我们告诉大家,大自然需要我们的帮助。', NULL, 'fable', 'dialogue', 34, 1, '[{"type": "choice", "q": "What does B know about planting trees?", "options": ["It costs money.", "It will help the air.", "It is boring.", "It takes years."], "answer": "B", "explanation": "''I know that it will help the air.''"}, {"type": "choice", "q": "What do they believe?", "options": ["Nature needs nothing.", "Trees are useless.", "Planting is too hard.", "Small actions can change a lot."], "answer": "D", "explanation": "''I believe that small actions can change a lot.''"}]'::jsonb, '[{"word": "hill", "cn": "小山"}, {"word": "ground", "cn": "土地,地面"}]'::jsonb),
  ('09bdf814-910d-e2ea-2762-decb0dfe29c6', 8, 'junior_fltrp', 'wy8B', 'U5', 'The secret world of the forest', '独白·森林秘密(宾从that)', 'Many people think that a forest is just a group of trees. But scientists have shown that a forest is a living family. They found that trees can share food through their roots. They also learnt that older trees protect the young ones. When one tree is ill, others know that it needs help, and they send it what it needs. I believe that we still understand very little about nature. The more we look, the more we see that the world is full of quiet wonders.', '很多人以为森林只是一群树。但科学家表明,森林是一个有生命的家庭。他们发现树能通过根分享食物。他们还了解到老树保护小树。当一棵树生病,别的树知道它需要帮助,就把它需要的送去。我相信我们对自然仍知之甚少。越看,越发现世界满是安静的奇迹。', NULL, 'fable', 'passage', 47, 1, '[{"type": "choice", "q": "What did scientists find trees can share through their roots?", "options": ["Food.", "Water only.", "Light.", "Air."], "answer": "A", "explanation": "''trees can share food through their roots.''"}, {"type": "choice", "q": "What does the writer believe about nature?", "options": ["It is simple.", "It is only trees.", "We still understand very little about it.", "It has no life."], "answer": "C", "explanation": "''I believe that we still understand very little about nature.''"}]'::jsonb, '[{"word": "roots", "cn": "根"}, {"word": "wonders", "cn": "奇迹"}]'::jsonb),
  ('86bfc5c6-6d4f-bbdf-cebf-e6d9b4cd5e8f', 8, 'junior_fltrp', 'wy8B', 'U5', 'What the river taught me', '独白·河的启示(宾从that)', 'Every summer, I sit by the river near my home, and it teaches me many things. I have learnt that water always finds a way, even around the biggest rocks. I have noticed that the river is never in a hurry, yet it reaches the sea in the end. Old people in my village say that the river has run here for a thousand years. I now understand that nature is patient and strong. I hope that one day I can be as calm and steady as this quiet river.', '每年夏天,我坐在家附近的河边,它教会我许多。我懂得水总能找到出路,即使绕过最大的石头。我注意到河从不着急,却终究流入大海。村里老人说这条河在这儿流了一千年。我现在明白自然耐心而强大。我希望有一天我能像这条安静的河一样平和坚定。', NULL, 'fable', 'passage', 49, 2, '[{"type": "choice", "q": "What has the writer learnt about water?", "options": ["It always finds a way.", "It is always in a hurry.", "It never reaches the sea.", "It is weak."], "answer": "A", "explanation": "''water always finds a way, even around the biggest rocks.''"}, {"type": "choice", "q": "What does the writer now understand about nature?", "options": ["Nature is fast and weak.", "Nature is patient and strong.", "Rivers are useless.", "Summers are short."], "answer": "B", "explanation": "''nature is patient and strong.''"}]'::jsonb, '[{"word": "rocks", "cn": "石头"}, {"word": "steady", "cn": "稳定的,坚定的"}]'::jsonb),
  ('6d64f122-9cc4-1d91-f56d-9c667edad39e', 8, 'junior_fltrp', 'wy8B', 'U5', 'Nature Week', '自然探索周(宾语从句 that)', 'Hello, students. Here is some news about our Nature Week. Some people think that nature is far, but we believe that it is all around us. Next week, we will look closely at the living world. On Monday, you will find that even a small garden has many living things. On Friday, share one new thing you have learnt about nature. Come and see how great nature is!', '同学们好,关于自然周的通知。有些人认为大自然离我们很远,但我们相信它就在身边。下周,我们会仔细观察生机勃勃的世界。周一,你会发现,哪怕一座小花园里也有许多生命。周五,分享一件你新学到的关于自然的事。来看看大自然多么了不起!', NULL, 'fable', 'notice', 37, 2, '[{"type": "choice", "q": "What will students find on Monday?", "options": ["Nothing lives in a garden.", "Gardens are boring.", "A small garden has many living things.", "Nature is far away."], "answer": "C", "explanation": "''you will find that even a small garden has many living things.''"}, {"type": "choice", "q": "What is Nature Week about?", "options": ["A shopping trip.", "A sports match.", "A music show.", "Discovering that nature is all around us."], "answer": "D", "explanation": "通知主体=发现自然就在身边(think/believe/find that...)。"}]'::jsonb, '[{"word": "nature", "cn": "自然;大自然"}, {"word": "garden", "cn": "花园"}]'::jsonb),
  ('9e959545-6365-462b-b08e-f6c974e06b2a', 8, 'junior_fltrp', 'wy8B', 'U6', 'I wonder if we can help', '疑问(宾从if/whether)', 'A: I wonder if we can do anything to help the birds this winter.
B: We can! Do you know what they need most?
A: I''m not sure whether it''s food or a warm place.
B: It''s both. Can you tell me how we make a bird feeder?
A: Sure. I''ll show you where to hang it too.
B: Great. Let''s find out which trees the birds like best.', 'A:我在想我们能不能做点什么帮冬天的鸟。B:能!你知道它们最需要什么吗?A:我不确定是食物还是温暖的地方。B:两样都要。你能告诉我怎么做喂鸟器吗?A:当然,我还会教你挂在哪。B:好,我们去弄清鸟最喜欢哪些树。', NULL, 'fable', 'dialogue', 37, 1, '[{"type": "choice", "q": "What is A not sure about?", "options": ["Where the birds live.", "When winter starts.", "Who feeds the birds.", "Whether the birds need food or a warm place."], "answer": "D", "explanation": "''I''m not sure whether it''s food or a warm place.''"}, {"type": "choice", "q": "What are the two friends planning to do?", "options": ["Help the birds get through winter.", "Catch the birds.", "Cut down trees.", "Buy a bird."], "answer": "A", "explanation": "计划帮鸟过冬。"}]'::jsonb, '[{"word": "feeder", "cn": "喂食器"}, {"word": "hang", "cn": "悬挂"}]'::jsonb),
  ('3bea461b-ecd9-9c9f-5543-29f45ea15cca', 8, 'junior_fltrp', 'wy8B', 'U6', 'Do you know why?', '疑问(宾从why/how)', 'A: Do you know why the river looks dirty these days?
B: I think people throw rubbish in it. I''m not sure how we can stop them.
A: Maybe we can show them what clean water means for fish.
B: Good idea. Can you tell me when the clean-up day is?
A: It''s this Saturday. I''ll ask who else wants to join.
B: Let''s find out whether the whole class can come.', 'A:你知道这条河为什么最近看着脏吗?B:我觉得人们往里扔垃圾,我不确定怎么阻止他们。A:也许我们能让他们明白干净水对鱼意味着什么。B:好主意,你能告诉我清理日是什么时候吗?A:这周六,我去问还有谁想参加。B:我们去弄清全班能不能来。', NULL, 'fable', 'dialogue', 39, 2, '[{"type": "choice", "q": "When is the clean-up day?", "options": ["Friday.", "Sunday.", "This Saturday.", "Next Monday."], "answer": "C", "explanation": "''It''s this Saturday.''"}, {"type": "choice", "q": "What are they trying to do?", "options": ["Catch fish.", "Clean the river and protect the fish.", "Throw rubbish.", "Close the river."], "answer": "B", "explanation": "清河、护鱼。"}]'::jsonb, '[{"word": "rubbish", "cn": "垃圾"}, {"word": "clean-up", "cn": "清理"}]'::jsonb),
  ('f3fe9b2e-d773-30d3-bd2f-9061b5cdfb2c', 8, 'junior_fltrp', 'wy8B', 'U6', 'Can you tell me how?', '疑问(宾从how/what)', 'A: Can you tell me how I can save water at home?
B: Sure. First, find out where water is wasted.
A: I don''t know what you mean.
B: For example, don''t leave the tap running when you brush your teeth.
A: Oh, I see! I''ll check whether my family does that too.
B: Good. Small habits decide how much we save.', 'A:你能告诉我在家怎么省水吗?B:当然,先弄清哪里在浪费水。A:我不明白你的意思。B:比如,刷牙时别让水龙头一直开着。A:哦,懂了!我去看看我家是不是也这样。B:好,小习惯决定我们能省多少。', NULL, 'fable', 'dialogue', 32, 1, '[{"type": "choice", "q": "What does B say not to do when brushing teeth?", "options": ["Use cold water.", "Sing a song.", "Close the door.", "Leave the tap running."], "answer": "D", "explanation": "''don''t leave the tap running when you brush your teeth.''"}, {"type": "choice", "q": "What is the dialogue mainly about?", "options": ["How to brush teeth.", "How to save water at home.", "Why water is dirty.", "How to wash clothes."], "answer": "B", "explanation": "主题=在家省水。"}]'::jsonb, '[{"word": "wasted", "cn": "浪费(waste的过去分词)"}, {"word": "tap", "cn": "水龙头"}]'::jsonb),
  ('11fa119a-fa33-eb39-1f8a-fe3a86159c57', 8, 'junior_fltrp', 'wy8B', 'U6', 'Living close to nature', '独白·亲近自然(宾从whether/how)', 'People often ask whether we can live close to nature in a busy city. I believe we can. Every morning, I wonder what small thing I can do for the earth. I check whether I have turned off the lights. I decide how I will travel: by bike, not by car. I have learnt where the nearest park is, and I visit it often. I cannot say whether my choices matter to the whole planet, but every small action makes me proud. Living with nature begins with small daily choices.', '人们常问,在繁忙的城市能不能亲近自然。我相信能。每天早上,我想我能为地球做点什么小事。我看看灯有没有关。我决定怎么出行:骑车而非开车。我知道了最近的公园在哪,常去。我不知道一个人能否改变世界,但我知道尝试的感觉多好。与自然共生始于每天的小选择。', NULL, 'fable', 'passage', 50, 1, '[{"type": "choice", "q": "How does the writer decide to travel?", "options": ["By bike.", "By car.", "By bus.", "By train."], "answer": "A", "explanation": "''I decide how I will travel: by bike, not by car.''"}, {"type": "choice", "q": "What is the main idea?", "options": ["Cities have no nature.", "One person can do nothing.", "Living with nature begins with small daily choices.", "Cars are the best."], "answer": "C", "explanation": "''Living with nature begins with small daily choices.''"}]'::jsonb, '[{"word": "earth", "cn": "地球"}, {"word": "choices", "cn": "选择"}]'::jsonb),
  ('bc478421-4890-da43-ed6a-3480772c073d', 8, 'junior_fltrp', 'wy8B', 'U6', 'The question that stayed with me', '独白·萦绕的问题(宾从whether/what)', 'Last year, a visitor asked our class a simple question: ''Do you know what the earth gives you every day?'' No one could answer at first. Then we began to think about whether we had ever said thank you to nature. The air we breathe, the water we drink, the food we eat — they all come from the earth. I still wonder how we can give something back. I have decided that I will waste less and care more. I am not sure whether it is enough, but every small step matters.', '去年,一位来访者问我们班一个简单问题:『你们知道地球每天给你们什么吗?』起初没人答得上来。然后我们开始思考,是否曾对自然说过谢谢。我们呼吸的空气、喝的水、吃的食物——都来自地球。我仍在想我们能怎样回报。我决定少浪费、多关心。我不确定这够不够,但每一小步都重要。', NULL, 'fable', 'passage', 50, 2, '[{"type": "choice", "q": "What question did the visitor ask?", "options": ["What the earth gives you every day.", "Where the earth is.", "When to plant trees.", "Who cleans the air."], "answer": "A", "explanation": "''Do you know what the earth gives you every day?''"}, {"type": "choice", "q": "What has the writer decided to do?", "options": ["Do nothing.", "Leave the city.", "Waste less and care more.", "Ask more questions."], "answer": "C", "explanation": "''I will waste less and care more.''"}]'::jsonb, '[{"word": "breathe", "cn": "呼吸"}, {"word": "matters", "cn": "要紧,重要"}]'::jsonb),
  ('65f1d1c4-785c-ef2d-851c-d3dae02f2c66', 8, 'junior_fltrp', 'wy8B', 'U6', 'Save Nature Week', '爱护自然周(宾语从句 if/whether/wh)', 'Hello, students. Here is some news about our Save Nature Week. Do you know how much water we waste each day? Next week, let''s find out. On Monday, check whether the taps at home drip. On Wednesday, learn where our rubbish goes. On Friday, we will decide what small changes we can make. Come and find out how we can live better with nature!', '同学们好,关于『爱护自然周』的通知。你知道我们每天浪费多少水吗?下周,让我们弄清楚。周一,检查家里的水龙头是否滴水。周三,了解我们的垃圾去了哪里。周五,我们一起决定能做出哪些小改变。来弄清楚如何与自然更好地相处吧!', NULL, 'fable', 'notice', 35, 2, '[{"type": "choice", "q": "What should students check on Monday?", "options": ["The weather.", "The homework.", "The rubbish bin.", "Whether the taps drip."], "answer": "D", "explanation": "''On Monday, check whether the taps at home drip.''"}, {"type": "choice", "q": "What is Save Nature Week about?", "options": ["A cooking class.", "Finding out how to live better with nature.", "A sports day.", "A book fair."], "answer": "B", "explanation": "通知主体=弄清如何与自然更好相处(how/whether/where/what)。"}]'::jsonb, '[{"word": "rubbish", "cn": "垃圾"}, {"word": "waste", "cn": "浪费"}]'::jsonb);

-- 断言
DO $$
DECLARE tot int; badq int; poll int; peru int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8B';
  IF tot<>36 THEN RAISE EXCEPTION 'total=% 期望36', tot; END IF;
  SELECT count(*) INTO badq FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8B' AND jsonb_array_length(questions)<>2;
  IF badq<>0 THEN RAISE EXCEPTION '题数≠2的篇=%', badq; END IF;
  SELECT count(*) INTO poll FROM public.junior_listening_exercises WHERE volume='wy8B' AND publisher<>'junior_fltrp';
  IF poll<>0 THEN RAISE EXCEPTION 'pep_polluted=%', poll; END IF;
  SELECT count(*) INTO peru FROM (SELECT unit FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8B' GROUP BY unit HAVING count(*)<>6) t;
  IF peru<>0 THEN RAISE EXCEPTION '每单元≠6篇的单元数=%', peru; END IF;
  RAISE NOTICE 'OK: wy8B 听力 % 篇 · 6单元各6 · 每篇2题', tot;
END $$;

COMMIT;
SELECT unit, count(*) 篇, sum((audio_url IS NULL)::int) 待生成音频 FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8B' GROUP BY unit ORDER BY unit;